// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { SpatialGrid, StaticGrid } from "../../../main/frontend/graph-explorer/spatial-grid.ts";

test('moving rectangles updates cells, oversized entries and stable IDs without stale hits', () => {
  const grid = new SpatialGrid(64), boxes = [];
  for (let i = 0; i < 100; i++) {
    boxes.push({minX: i * 20, minY: 0, maxX: i * 20 + 10, maxY: 10});
    assert.equal(grid.insert(boxes[i]), i);
  }
  for (let i = 0; i < 300; i++) {
    const id = i % 100, x = i * 33 - 2000, width = i % 7 ? 20 : 30000;
    boxes[id] = {minX: x, minY: -200, maxX: x + width, maxY: 150};
    grid.update(id, boxes[id]);
    const query = {minX: -500, minY: -10, maxX: 700, maxY: 10};
    const expected = boxes.flatMap((b, j) => b.maxX >= query.minX && b.minX <= query.maxX && b.maxY >= query.minY && b.minY <= query.maxY ? [j] : []);
    assert.deepEqual(grid.search(query.minX, query.minY, query.maxX, query.maxY), expected);
  }
  assert.throws(() => grid.update(1000, boxes[0]), RangeError);
  assert.throws(() => grid.update(0, {...boxes[0], minX: NaN}), RangeError);
});

test("spatial queries match exhaustive rectangle tests, including touching and negative bounds", () => {
  const grid = new SpatialGrid(64), boxes = [];
  let seed = 813;
  const random = () => ((seed = Math.imul(seed, 1664525) + 1013904223 >>> 0) / 2 ** 32);
  for (let i = 0; i < 500; i++) {
    const minX = Math.floor(random() * 2400 - 1200), minY = Math.floor(random() * 1800 - 900);
    const bounds = {minX, minY, maxX: minX + random() * 300, maxY: minY + random() * 120};
    boxes.push(bounds); grid.insert(bounds);
  }
  boxes.push({minX: -1e9, minY: -1e9, maxX: 1e9, maxY: 1e9}); grid.insert(boxes.at(-1));
  const buffer = [];
  for (const query of [...boxes, {minX: -1e10, minY: -1e10, maxX: 1e10, maxY: 1e10}]) {
    const {minX, minY, maxX, maxY} = query;
    const expected = boxes.flatMap((b, i) => b.maxX >= minX && b.minX <= maxX && b.maxY >= minY && b.minY <= maxY ? [i] : []);
    assert.equal(grid.search(minX, minY, maxX, maxY, buffer), buffer);
    assert.deepEqual(buffer, expected);
  }
});

test("invalid and extreme coordinates cannot create unbounded grid loops", () => {
  assert.throws(() => new SpatialGrid(0), RangeError);
  const grid = new SpatialGrid();
  assert.throws(() => grid.insert({minX: NaN, minY: 0, maxX: 0, maxY: 0}), RangeError);
  grid.insert({minX: 1e30, maxX: 1e30, minY: 1e30, maxY: 1e30});
  assert.deepEqual(grid.search(1e30, 1e30, 1e30, 1e30), [0]);
  assert.deepEqual(grid.search(0, 0, Infinity, 1), []);
});

test("a static grid answers every search as the dynamic grid and an exhaustive test do, in ascending order", () => {
  let seed = 4711;
  const random = () => ((seed = Math.imul(seed, 1664525) + 1013904223 >>> 0) / 2 ** 32);
  for (const [count, spread] of [[0, 100], [1, 100], [40, 300], [700, 4000], [3000, 20000], [200, 1e7]]) {
    const boxes = Array.from({length: count}, (_, i) => {
      const minX = (random() - 0.5) * spread, minY = (random() - 0.5) * spread;
      // Some boxes are wide enough to span many cells; one in fifty is a point.
      const width = i % 50 ? random() * (i % 7 ? 300 : 5000) : 0, height = i % 50 ? random() * 120 : 0;
      return {minX, minY, maxX: minX + width, maxY: minY + height};
    });
    const column = (key) => Float64Array.from(boxes, (b) => b[key]);
    const fixed = new StaticGrid(column("minX"), column("minY"), column("maxX"), column("maxY"));
    const dynamic = new SpatialGrid(256);
    boxes.forEach((b) => dynamic.insert(b));
    const queries = [...boxes.slice(0, 300), {minX: -1e10, minY: -1e10, maxX: 1e10, maxY: 1e10}, {minX: 0, minY: 0, maxX: 0, maxY: 0},
      {minX: 5, minY: 5, maxX: 4, maxY: 6}, {minX: NaN, minY: 0, maxX: 1, maxY: 1}, {minX: 0, minY: 0, maxX: Infinity, maxY: 1}];
    for (let q = 0; q < 300; q++) {
      const minX = (random() - 0.5) * spread * 1.2, minY = (random() - 0.5) * spread * 1.2;
      queries.push({minX, minY, maxX: minX + random() * spread / 3, maxY: minY + random() * spread / 3});
    }
    const buffer = [];
    for (const {minX, minY, maxX, maxY} of queries) {
      const valid = [minX, minY, maxX, maxY].every(Number.isFinite) && minX <= maxX && minY <= maxY;
      const expected = valid ? boxes.flatMap((b, i) => (b.maxX >= minX && b.minX <= maxX && b.maxY >= minY && b.minY <= maxY ? [i] : [])) : [];
      assert.equal(fixed.search(minX, minY, maxX, maxY, buffer), buffer);
      assert.deepEqual(buffer, expected, JSON.stringify({count, minX, minY, maxX, maxY}));
      assert.deepEqual(dynamic.search(minX, minY, maxX, maxY), expected);
    }
  }
  const extreme = new StaticGrid(Float64Array.of(-1.7e308, 0), Float64Array.of(0, 0), Float64Array.of(-1.7e308, 1.7e308), Float64Array.of(1, 1));
  assert.deepEqual(extreme.search(-1e308, 0, 1e308, 1), [1]);
  assert.deepEqual(extreme.search(-1.7e308, 0, -1.7e308, 0), [0]);
  assert.throws(() => new StaticGrid(Float64Array.of(0), Float64Array.of(0), Float64Array.of(NaN), Float64Array.of(0)), RangeError);
  assert.throws(() => new StaticGrid(Float64Array.of(2), Float64Array.of(0), Float64Array.of(1), Float64Array.of(0)), RangeError);
});
